.tp-side-right{right:120px;background:var(--side-b,var(--panel))}
.tp-side-label{font-family:var(--f-label);font-size:26px;letter-spacing:.18em;text-transform:uppercase;color:var(--panel-accent,var(--accent));font-weight:var(--w-label,700);line-height:1.3}
.tp-side-value{font-family:var(--f-display);font-weight:var(--w-display,700);font-size:130px;line-height:1;white-space:nowrap;color:var(--panel-ink)}
.tp-points{list-style:none;display:flex;flex-direction:column;gap:14px}
.tp-points li{font-size:32px;line-height:1.3;padding-left:38px;position:relative}
.tp-points li::before{content:'';position:absolute;left:0;top:.6em;width:18px;height:4px;background:var(--panel-accent,var(--accent))}
.tp-side-right .tp-side-label,.tp-side-right .tp-points li::before{color:var(--side-b-accent,var(--panel-accent,var(--accent)))}
.tp-side-right{color:var(--side-b-ink,var(--panel-ink))}
.tp-side-right .tp-side-value{color:var(--side-b-ink,var(--panel-ink))}
.tp-side-right .tp-points li::before{background:var(--side-b-accent,var(--panel-accent,var(--accent)))}
.tp-vs-mark{position:absolute;left:944px;top:654px;width:32px;height:32px;transform:rotate(45deg);background:var(--accent);z-index:4}

/* steps */
.tp-steplist{position:absolute;left:120px;right:120px;top:420px;height:500px;display:grid;gap:36px;list-style:none;z-index:3}
.n-3 .tp-steplist{grid-template-columns:repeat(3,minmax(0,1fr))}
.n-4 .tp-steplist{grid-template-columns:repeat(4,minmax(0,1fr))}
.n-5 .tp-steplist{grid-template-columns:repeat(5,minmax(0,1fr));gap:28px}
.tp-step{position:relative;height:100%;gap:20px;padding-top:30px;border-top:6px solid var(--accent)}
.tp-step-n{font-family:var(--f-display);font-weight:var(--w-display,700);font-size:72px;line-height:1;color:var(--accent)}
.tp-step-body{display:flex;flex-direction:column;gap:12px;min-width:0}
.tp-step-head{font-size:40px;font-weight:700;line-height:1.18;color:var(--ink)}
.tp-step-text{font-size:28px;line-height:1.4;color:var(--muted)}
.n-5 .tp-step-head{font-size:34px}
.n-5 .tp-step-text{font-size:25px}

/* quote */
.tp-quote-mark{position:absolute;left:150px;top:70px;font-family:var(--f-quote,var(--f-display));font-size:340px;line-height:1;color:var(--accent);z-index:2;height:260px;overflow:hidden}
.tp-quote-box{left:260px;top:300px;width:1420px;height:600px;justify-content:center;gap:30px}
.tp-quote-text{font-family:var(--f-quote,var(--f-display));font-size:78px;line-height:1.18;font-style:var(--fs-quote,normal);font-weight:var(--w-quote,500);color:var(--ink)}
.tp-quote-by{font-size:32px;font-weight:700;line-height:1.3;color:var(--ink)}
.tp-quote-role{font-size:26px;line-height:1.3;color:var(--muted)}

/* bars */
.tp-chart{position:absolute;left:120px;right:120px;top:420px;height:510px;display:flex;gap:32px;z-index:3}
.tp-bar{position:relative;flex:1 1 0;min-width:0;display:flex;flex-direction:column;gap:16px}
.tp-bar-track{position:relative;flex:1 1 auto}
.tp-bar-fill{position:absolute;left:0;right:0;bottom:0;height:calc((100% - 80px) * var(--hf));background:var(--bar,var(--rule));border-radius:var(--bar-radius,0)}
.tp-bar.is-top .tp-bar-fill{background:var(--accent)}
.tp-bar-value{position:absolute;left:0;right:0;bottom:calc((100% - 80px) * var(--hf) + 14px);font-family:var(--f-display);font-weight:var(--w-display,700);font-size:52px;line-height:1;white-space:nowrap;color:var(--ink)}
.tp-bar-label{font-family:var(--f-label);font-size:24px;line-height:1.25;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);height:62px}

/* image */
.tp-media{position:absolute;right:0;top:0;width:880px;height:1080px;margin:0;overflow:hidden;z-index:2}
.tp-media img.photo{display:block;width:100%;height:100%;object-fit:cover}
.tp-image-text{left:120px;top:120px;width:800px;height:820px;justify-content:center;gap:24px}
.tp-image .tp-title{font-size:84px}
.tp-body{font-size:32px;line-height:1.45;color:var(--muted)}
.tp-image .tp-points li::before{background:var(--accent)}
.tp-image .tp-foot{right:960px}

/* section */
.tp-section-text{left:120px;top:180px;width:1520px;height:700px;justify-content:center;gap:30px}
.tp-section .tp-title{font-size:150px}
.tp-sub{font-size:38px;line-height:1.4;color:var(--muted)}


