lifestyle.css:
.slide.tp{position:relative;width:1920px;height:1080px;overflow:hidden;background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:28px;line-height:1.4;-webkit-font-smoothing:antialiased;text-rendering:geometricPrecision}
.tp *{margin:0;padding:0;box-sizing:border-box}
.tp-bg{position:absolute;inset:0;z-index:0;overflow:hidden}
.tp-bg img.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.tp-shade{position:absolute;inset:0}
.tp-decor{position:absolute;inset:0;z-index:1;pointer-events:none}
.tp-box{position:absolute;z-index:3;display:flex;flex-direction:column;min-width:0}
.tp-box>*{flex-shrink:0;max-width:100%}
.tp-kicker{font-family:var(--f-label);font-weight:var(--w-label,700);font-size:24px;letter-spacing:var(--ls-label,.24em);text-transform:var(--tt-label,uppercase);color:var(--accent);line-height:1.3}
.tp-title{font-family:var(--f-display);font-weight:var(--w-display,700);line-height:var(--lh-display,1);letter-spacing:var(--ls-display,0);text-transform:var(--tt-display,none);color:var(--ink);overflow-wrap:break-word}
.tp-rule{width:120px;height:6px;background:var(--accent)}
.tp-foot{position:absolute;left:120px;right:120px;bottom:46px;display:flex;justify-content:space-between;align-items:baseline;gap:40px;z-index:4;font-family:var(--f-label);font-size:20px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);line-height:1.2}
.tp-photo{position:absolute;z-index:2;overflow:hidden;margin:0}
.tp-photo img.portrait{display:block;width:100%;height:100%;object-fit:cover;object-position:50% 22%}
.tp-logo{position:absolute;z-index:3;margin:0;display:flex;align-items:center}
.tp-logo img{max-width:100%;max-height:100%;object-fit:contain}
.tp-by-name{font-family:var(--f-body);font-weight:700;font-size:36px;line-height:1.2;color:var(--ink)}
.tp-by-role{font-size:26px;line-height:1.3;color:var(--muted)}

/* cover */
.tp-cover .tp-cover-text{left:120px;top:140px;width:1000px;height:660px;justify-content:center;gap:30px}
.tp-cover.no-photo .tp-cover-text{width:1480px}
.tp-cover .tp-title{font-size:132px}
.tp-cover .tp-photo{right:120px;top:120px;width:560px;height:720px}
.tp-cover .tp-by{left:120px;bottom:96px;width:1000px;height:120px;justify-content:center;gap:4px}
.tp-cover .tp-logo{right:120px;bottom:96px;width:420px;height:150px;justify-content:flex-end}

/* closing */
.tp-closing .tp-photo{left:0;top:0;width:720px;height:1080px}
.tp-closing .tp-close-text{left:820px;top:120px;width:980px;height:840px;justify-content:center;gap:20px}
.tp-closing.no-photo .tp-close-text{left:120px;width:1480px}
.tp-closing .tp-title{font-size:120px;margin-bottom:12px}
.tp-contact{display:flex;flex-direction:column;gap:6px;margin-top:8px}
.tp-contact-line{font-size:32px;line-height:1.35;color:var(--ink)}
.tp-cta{align-self:flex-start;margin-top:14px;padding:20px 34px;background:var(--accent);color:var(--accent-ink);font-weight:800;font-size:28px;line-height:1.2;border-radius:var(--radius,10px);white-space:nowrap}
.tp-closing .tp-logo{right:120px;bottom:96px;width:360px;height:140px;justify-content:flex-end}

/* big number */
.tp-bignumber .tp-num-text{left:120px;top:130px;width:1680px;height:780px;justify-content:center;gap:18px}
.tp-bignumber.has-was .tp-num-text{width:1160px}
.tp-value{font-family:var(--f-num,var(--f-display));font-weight:var(--w-num,var(--w-display,700));font-size:380px;line-height:.92;white-space:nowrap;color:var(--accent);letter-spacing:-.02em}
.tp-unit{font-size:54px;line-height:1.15;font-weight:600;color:var(--ink)}
.tp-line{font-size:36px;line-height:1.4;color:var(--muted);max-width:1100px}
.tp-was{right:120px;top:360px;width:440px;height:360px;justify-content:center;align-items:flex-start;gap:10px;padding-left:40px;border-left:4px solid var(--rule)}
.tp-was-label{font-family:var(--f-label);font-size:24px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);line-height:1.3}
.tp-was-value{font-family:var(--f-display);font-weight:var(--w-display,700);font-size:96px;line-height:1.05;white-space:nowrap;color:var(--muted);text-decoration:line-through;text-decoration-color:var(--strike,var(--accent));text-decoration-thickness:6px}

/* the heading over cards, comparisons, steps and charts */
.tp-head{left:120px;top:96px;width:1680px;height:270px;justify-content:flex-end;gap:16px}
.tp-head .tp-title{font-size:84px}
.tp-note{font-size:28px;line-height:1.35;color:var(--muted)}

/* cards */
.tp-cardrow{position:absolute;left:120px;right:120px;top:420px;height:500px;display:grid;gap:36px;z-index:3}
.n-2 .tp-cardrow{grid-template-columns:repeat(2,minmax(0,1fr))}
.n-3 .tp-cardrow{grid-template-columns:repeat(3,minmax(0,1fr))}
.n-4 .tp-cardrow{grid-template-columns:repeat(4,minmax(0,1fr));gap:28px}
.tp-card{position:relative;height:100%;padding:44px 40px;gap:14px;background:var(--panel);color:var(--panel-ink);border-radius:var(--radius,10px);justify-content:flex-end}
.tp-card-n{font-family:var(--f-label);font-size:22px;letter-spacing:.2em;color:var(--panel-accent,var(--accent));margin-bottom:auto;line-height:1}
.tp-card-value{font-family:var(--f-display);font-weight:var(--w-display,700);font-size:120px;line-height:1;white-space:nowrap;color:var(--panel-ink);text-transform:var(--tt-display,none)}
.tp-card-label{font-size:34px;font-weight:600;line-height:1.25;color:var(--panel-ink)}
.tp-card-note{font-size:26px;line-height:1.35;color:var(--panel-muted,var(--muted))}

/* compare */
.tp-side{top:420px;height:500px;width:800px;padding:48px 52px;gap:18px;background:var(--panel);color:var(--panel-ink);border-radius:var(--radius,10px)}
.tp-side-left{left:120px}
.tp-side-right{right:120px;background:var(--side-b,var(--panel))}
.tp-side-label{font-family:var(--f-label);font-size:26px;letter-spacing:.18em;text-transform:uppercase;color:var(--panel-accent,var(--accent));font-weight:var(--w-label,700);line-height:1.3}
.tp-side-value{font-family:var(--f-display);font-weight:var(--w-display,700);font-size:130px;line-height:1;white-space:nowrap;color:var(--panel-ink)}
.tp-points{list-style:none;display:flex;flex-direction:column;gap:14px}
.tp-points li{font-size:32px;line-height:1.3;padding-left:38px;position:relative}
.tp-points li::before{content:'';position:absolute;left:0;top:.6em;width:18px;height:4px;background:var(--panel-accent,var(--accent))}
.tp-side-right .tp-side-label,.tp-side-right .tp-points li::before{color:var(--side-b-accent,var(--panel-accent,var(--accent)))}
.tp-side-right{color:var(--side-b-ink,var(--panel-ink))}
.tp-side-right .tp-side-value{color:var(--side-b-ink,var(--panel-ink))}
.tp-side-right .tp-points li::before{background:var(--side-b-accent,var(--panel-accent,var(--accent)))}
.tp-vs-mark{position:absolute;left:944px;top:654px;width:32px;height:32px;transform:rotate(45deg);background:var(--accent);z-index:4}

/* steps */
.tp-steplist{position:absolute;left:120px;right:120px;top:420px;height:500px;display:grid;gap:36px;list-style:none;z-index:3}
.n-3 .tp-steplist{grid-template-columns:repeat(3,minmax(0,1fr))}
.n-4 .tp-steplist{grid-template-columns:repeat(4,minmax(0,1fr))}
.n-5 .tp-steplist{grid-template-columns:repeat(5,minmax(0,1fr));gap:28px}
.tp-step{position:relative;height:100%;gap:20px;padding-top:30px;border-top:6px solid var(--accent)}
.tp-step-n{font-family:var(--f-display);font-weight:var(--w-display,700);font-size:72px;line-height:1;color:var(--accent)}
.tp-step-body{display:flex;flex-direction:column;gap:12px;min-width:0}
.tp-step-head{font-size:40px;font-weight:700;line-height:1.18;color:var(--ink)}
.tp-step-text{font-size:28px;line-height:1.4;color:var(--muted)}
.n-5 .tp-step-head{font-size:34px}
.n-5 .tp-step-text{font-size:25px}

/* quote */
.tp-quote-mark{position:absolute;left:150px;top:70px;font-family:var(--f-quote,var(--f-display));font-size:340px;line-height:1;color:var(--accent);z-index:2;height:260px;overflow:hidden}
.tp-quote-box{left:260px;top:300px;width:1420px;height:600px;justify-content:center;gap:30px}
.tp-quote-text{font-family:var(--f-quote,var(--f-display));font-size:78px;line-height:1.18;font-style:var(--fs-quote,normal);font-weight:var(--w-quote,500);color:var(--ink)}
